import React, { useEffect, useRef, useState } from 'react'
import { useLocation } from 'react-router-dom'
import { ToastContainer } from 'react-toastify'
import useApi from '../../../../hooks/useApi'
import paymentsApi from '../../../../api/paymentsApi'
import { usePageVisibility } from '../../../../hooks/userPageVisibility'
import saccosApi from '../../../../api/saccos/saccosApi'

export default function MembersAccountDetails() {
    const location = useLocation()

    const [item, setitem] = React.useState(location.state.item ? location.state.item : null)

    const accountBalanceApi = useApi(saccosApi.saccoMemberAction);

    // eslint-disable-next-line react-hooks/exhaustive-deps
    const getAccountStatus = async () => {
        accountBalanceApi.request({
    "action":"MemberAccountBalance",
    "accountNumber":item.accountNumber

});
    };

    useEffect(() => {
        if (item) {
            console.log("item", item)
              getAccountStatus();
        }
      
    }, [item]);


    useEffect(() => {
       console.log("accountBalanceApi", accountBalanceApi.data)
        if (accountBalanceApi.data) {

            setaccountBalance(accountBalanceApi.data.balance.balance)
        }

         
    }, [accountBalanceApi.data]);

    useEffect(() => { console.log("item", item) }, [item])

    const [accountBalance, setaccountBalance] = useState("0.00")

    const isPageVisible = usePageVisibility();
    const timerIdRef = useRef(null);
    const [isPollingEnabled, setIsPollingEnabled] = useState(true);

    useEffect(() => {
        const pollingCallback = () => {
            // Your polling logic here
            console.log("Polling...");
            getAccountStatus();
        };

        const startPolling = () => {
            // pollingCallback(); // To immediately start fetching data
            // Polling every 10 seconds
            timerIdRef.current = setInterval(pollingCallback, 5000);
        };

        const stopPolling = () => {
            clearInterval(timerIdRef.current);
        };

        if (isPageVisible && isPollingEnabled) {
            startPolling();
        } else {
            stopPolling();
        }

        return () => {
            stopPolling();
        };
    }, [isPageVisible, isPollingEnabled, getAccountStatus]);

    return (
        <div className="mt-16 md:mt-2 grid grid-cols-1 md:grid-cols-12 bg-gray-50 py-5">
            <div className="col-span-2 hidden md:block"></div>
            <div className="col-span-8  bg-gray-100 items-center justify-center">
                <div>
                    <ToastContainer theme="colored" position="bottom-center" />
                    <p className='font-semibold text-center text-lg'>{item.accountName}</p>
                    {accountBalance&&<p className='font-bold text-center text-2xl'>{accountBalance}</p>}
                     <p className=' text-center text-lg'>KES</p>
 <p className='font-semibold text-center text-lg'>{item.accountNumber}</p>
                </div>
            </div>
            <div className="col-span-2 hidden md:block"></div>
        </div>
    )
}
